body{{font-family:Arial,sans-serif;margin:24px;background:#f6f8fb;color:#1f2937;line-height:1.45}} .container{{max-width:1200px;margin:auto;background:#fff;padding:28px;border-radius:12px;box-shadow:0 2px 10px rgba(0,0,0,.06)}}
