new Chart(document.getElementById('riskByExperience'),{{type:'bar',data:{{labels:ex.map(d=>d.experience_level),datasets:[{{label:'Avg AI Risk',data:ex.map(d=>d.avg_ai_risk)}},{{label:'Survival Rate',data:ex.map(d=>d.survival_rate)}}]}},options:{{plugins:{{title:{{display:true,text:'Risk vs Survival by Experience'}}}},scales:{{y:{{min:0,max:1}}}}}});
